-- Table: accounting_expense_detail
-- Source: accounting_admin_db.sql (6. Accounting expense, reconciliation, and period closing)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS accounting_expense_detail (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    expense_id           BIGINT NOT NULL REFERENCES accounting_expense(id) ON DELETE CASCADE,
    line_number          INTEGER NOT NULL CHECK (line_number > 0),
    coa_id               BIGINT NOT NULL REFERENCES masterdata_coa(id),
    description          TEXT,
    amount               NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (amount >= 0),
    tax_rate_id          BIGINT REFERENCES masterdata_tax_rate(id),
    tax_amount           NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (tax_amount >= 0),
    total                NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (total >= 0),
    budget_allocation_id BIGINT REFERENCES budget_allocation_detail(id),
    UNIQUE (expense_id, line_number)
);
